// ===================== FIGHTER ANIMATION =====================
function updateMotionVisuals(rig, entity, stance, isEnemy, dt) {
  if (!rig?.motionSprite) return;
  const now = performance.now();
  const action = ['PUNCH', 'KICK', 'SUPER'].includes(stance);
  const hit = (entity.hitFlash || 0) > 0;
  const pulse = 1 + Math.sin(now * 0.006 + (isEnemy ? 1.8 : 0)) * 0.035;
  const lean = action ? (isEnemy ? -0.08 : 0.08) : 0;
  const baseX = rig.group.position.x + lean;
  const baseY = 1.02 + (rig.hips.position.y - 1.02) * 0.45;
  rig.motionSprite.position.set(baseX, baseY, rig.group.position.z - 0.14);
  rig.motionSprite.scale.set(2.46 * pulse * (action ? 1.08 : 1), 3.0 * pulse * (stance === 'CROUCH' ? 0.82 : 1), 1);
  rig.motionSprite.material.opacity = hit ? 0.30 : (action ? 0.22 : 0.12);
  rig.motionSprite.material.rotation = Math.sin(now * 0.003) * 0.015 + (entity.knockback || 0) * 0.02;

  const echoStrength = action ? 0.18 : hit ? 0.10 : 0;
  rig.afterimages.forEach((sprite, index) => {
    const age = (index + 1) / rig.afterimages.length;
    sprite.position.set(baseX - (isEnemy ? -1 : 1) * age * (action ? 0.32 : 0.08), baseY, rig.group.position.z - 0.22 - age * 0.03);
    sprite.scale.set(2.46 * pulse, 3.0 * pulse, 1);
    sprite.material.opacity = echoStrength * (1 - age) * (0.8 + Math.sin(now * 0.008 + index) * 0.2);
    sprite.material.rotation = (isEnemy ? -1 : 1) * age * (action ? 0.10 : 0.025);
  });
}
function updateFighterRig(rig, entity, stance, isEnemy, dt) {
  const c = rig.cur;
  let tShoulderL = 0, tElbowL = 0, tShoulderR = 0, tElbowR = 0;
  let tHipL = 0, tKneeL = 0, tHipR = 0, tKneeR = 0, tHipsY = 0, tTurn = 0, tBend = 0;

  const liveLm = isEnemy ? (dualCamMode ? p2LiveLandmarks : null) : livePoseLandmarks;
  if (liveLm) {
    const nose = liveLm[0], shL = liveLm[11], shR = liveLm[12];
    const elL = liveLm[13], elR = liveLm[14], wrL = liveLm[15], wrR = liveLm[16];
    const hipL = liveLm[23], hipR = liveLm[24], knL = liveLm[25], knR = liveLm[26];
    const anL = liveLm[27], anR = liveLm[28];
    tShoulderR = Math.atan2(elR.y - shR.y, elR.x - shR.x) + Math.PI / 2;
    tElbowR = Math.atan2(wrR.y - elR.y, wrR.x - elR.x) - tShoulderR + Math.PI / 2;
    tShoulderL = Math.atan2(elL.y - shL.y, elL.x - shL.x) + Math.PI / 2;
    tElbowL = Math.atan2(wrL.y - elL.y, wrL.x - elL.x) - tShoulderL + Math.PI / 2;
    tHipR = Math.atan2(knR.y - hipR.y, knR.x - hipR.x) + Math.PI / 2;
    tKneeR = Math.atan2(anR.y - knR.y, anR.x - knR.x) - tHipR + Math.PI / 2;
    tHipL = Math.atan2(knL.y - hipL.y, knL.x - hipL.x) + Math.PI / 2;
    tKneeL = Math.atan2(anL.y - knL.y, anL.x - knL.x) - tHipL + Math.PI / 2;
    tHipsY = THREE.MathUtils.clamp((0.55 - (hipL.y + hipR.y) / 2) * 3.0, -0.55, 0.4);
    tTurn = THREE.MathUtils.clamp((nose.x - (shL.x + shR.x) / 2) * 2.2, -0.6, 0.6);
  } else {
    const t = performance.now() * 0.004;
    if (stance === 'CROUCH') { tHipsY = -0.42; tHipL = 0.5; tHipR = -0.5; tKneeL = 0.7; tKneeR = -0.7; }
    else if (stance === 'PUNCH') { if (!isEnemy) { tShoulderR = Math.PI / 2.1; tElbowR = 0.1; } else { tShoulderL = -Math.PI / 2.1; tElbowL = -0.1; } }
    else if (stance === 'KICK') { if (!isEnemy) { tHipR = -Math.PI / 2.3; tKneeR = 0.5; } else { tHipL = Math.PI / 2.3; tKneeL = -0.5; } }
    else if (stance === 'GUARD') { tShoulderL = -0.75; tElbowL = 0.5; tShoulderR = 0.75; tElbowR = -0.5; }
    else if (stance === 'CHARGING') { tShoulderL = -1.1; tElbowL = 0.9; tShoulderR = 1.1; tElbowR = -0.9; tHipsY = Math.sin(t * 6) * 0.02; }
    else { tHipsY = Math.sin(t * 2.5) * 0.04; tShoulderL = Math.sin(t * 2.5) * 0.08 - 0.1; tShoulderR = -Math.sin(t * 2.5) * 0.08 + 0.1; }
  }

  tBend += (entity.knockback || 0) * 0.6;
  const s = 1 - Math.pow(0.001, dt);
  c.shoulderL = lerpAngle(c.shoulderL, tShoulderL, s); c.elbowL = lerpAngle(c.elbowL, tElbowL, s);
  c.shoulderR = lerpAngle(c.shoulderR, tShoulderR, s); c.elbowR = lerpAngle(c.elbowR, tElbowR, s);
  c.hipL = lerpAngle(c.hipL, tHipL, s); c.kneeL = lerpAngle(c.kneeL, tKneeL, s);
  c.hipR = lerpAngle(c.hipR, tHipR, s); c.kneeR = lerpAngle(c.kneeR, tKneeR, s);
  c.headTurn = lerp(c.headTurn, tTurn, s); c.hipsY = lerp(c.hipsY, tHipsY, s);

  rig.armL.shoulder.rotation.z = c.shoulderL; rig.armL.elbow.rotation.z = c.elbowL;
  rig.armR.shoulder.rotation.z = c.shoulderR; rig.armR.elbow.rotation.z = c.elbowR;
  rig.legL.hipPivot.rotation.z = c.hipL; rig.legL.knee.rotation.z = c.kneeL;
  rig.legR.hipPivot.rotation.z = c.hipR; rig.legR.knee.rotation.z = c.kneeR;
  rig.headGroup.rotation.z = c.headTurn;
  rig.hips.position.y = 1.02 + c.hipsY;
  rig.hips.rotation.z = tBend * 0.3;

  const kb = entity.knockback || 0;
  if (kb !== 0) {
    rig.group.position.x += -kb * 0.05;
    entity.knockback *= 0.8;
    if (Math.abs(entity.knockback) < 0.01) entity.knockback = 0;
  }
  const homeX = (entity === player ? player.homeX : ai.homeX) ?? (isEnemy ? 3.2 : -3.2);
  rig.group.position.x = lerp(rig.group.position.x, homeX, 0.06);
  if (!isEnemy) rig.group.position.z = lerp(rig.group.position.z, entity.dodgeZ || 0, 0.15);

  if (entity.hitFlash > 0) {
    entity.hitFlash = Math.max(0, entity.hitFlash - 0.06);
    rig.coreLight.intensity = 1.8 + entity.hitFlash * 4;
  } else { rig.coreLight.intensity = 1.8; }
  if (rig.aura) rig.aura.position.set(rig.group.position.x, 0.05, 0);
  updateMotionVisuals(rig, entity, stance, isEnemy, dt);
}


// ===================== RENDER LOOP =====================
function renderAnimeOverlayFX() {
  fxCtx.clearRect(0, 0, fxCanvas.width, fxCanvas.height);
  if (splitScreenOn) {
    const midX = fxCanvas.width / 2;
    fxCtx.strokeStyle = 'rgba(148,163,184,0.4)'; fxCtx.lineWidth = 2;
    fxCtx.beginPath(); fxCtx.moveTo(midX, 0); fxCtx.lineTo(midX, fxCanvas.height); fxCtx.stroke();
  }
  if (speedLinesActive && reducedMotion) { speedLinesTimer--; if (speedLinesTimer <= 0) speedLinesActive = false; }
  else if (speedLinesActive) {
    fxCtx.strokeStyle = 'rgba(56,189,248,0.2)'; fxCtx.lineWidth = 2;
    const cx = fxCanvas.width / 2, cy = fxCanvas.height / 2;
    for (let i = 0; i < 40; i++) {
      const angle = Math.random() * Math.PI * 2, dist = 100 + Math.random() * 300;
      fxCtx.beginPath();
      fxCtx.moveTo(cx + Math.cos(angle) * dist, cy + Math.sin(angle) * dist);
      fxCtx.lineTo(cx + Math.cos(angle) * (dist + 200), cy + Math.sin(angle) * (dist + 200));
      fxCtx.stroke();
    }
    speedLinesTimer--; if (speedLinesTimer <= 0) speedLinesActive = false;
  }
  for (let i = floatingTexts.length - 1; i >= 0; i--) {
    const ft = floatingTexts[i];
    fxCtx.font = '700 16px Orbitron'; fxCtx.fillStyle = ft.color; fxCtx.globalAlpha = ft.life;
    fxCtx.fillText(ft.text, ft.x, ft.y);
    ft.y += ft.vy; ft.life -= 0.025;
    if (ft.life <= 0) floatingTexts.splice(i, 1);
  }
  fxCtx.globalAlpha = 1.0;
}

function runFrame(now) {
  let delta = now - lastTime; lastTime = now;
  if (gameState === 'PAUSED') { renderSceneView(); return; }
  // Slow motion effect
  if (slowMotionActive) delta *= 0.3;
  if (hitStopFrames > 0) { hitStopFrames--; delta *= 0.15; }
  const dt = Math.min(delta, 50) / 1000;

  // Resize the FX canvas only when the on-screen size actually changes.
  // Reassigning `width` / `height` clears the canvas and resets the 2D
  // context state, so doing it 60×/s for no reason is wasted work.
  if (fxCanvas._lastW !== fxCanvas.clientWidth || fxCanvas._lastH !== fxCanvas.clientHeight) {
    fxCanvas.width = fxCanvas.clientWidth;
    fxCanvas.height = fxCanvas.clientHeight;
    fxCanvas._lastW = fxCanvas.width;
    fxCanvas._lastH = fxCanvas.height;
  }

  if (cameraShake > 0) {
    const shakeScale = reducedMotion ? 0.2 : 1;
    camera.position.x += (Math.random() - 0.5) * 0.22 * (cameraShake / 8) * shakeScale;
    camera.position.y += (Math.random() - 0.5) * 0.2 * (cameraShake / 8) * shakeScale;
    cameraShake = Math.max(0, cameraShake - 1);
  }
  updateMainCameraView();

  if (playerFighter3D) updateFighterRig(playerFighter3D, player, player.stance, false, dt);
  if (aiFighter3D) updateFighterRig(aiFighter3D, ai, ai.stance, true, dt);
  if (playerFighter3D && aiFighter3D) updateSplitCameras();
  if (dualCamMode && gameState === 'PLAYING') checkDualCamCollisions(dt);

  for (let i = particles3D.length - 1; i >= 0; i--) {
    const p = particles3D[i];
    p.position.x += p.userData.vx; p.position.y += p.userData.vy; p.position.z += p.userData.vz;
    p.userData.vy -= 0.01;
    p.userData.life -= 0.045; p.scale.setScalar(Math.max(0, p.userData.life));
    if (p.userData.life <= 0) { scene.remove(p); p.material?.dispose(); particles3D.splice(i, 1); }
  }

  renderSceneView();
  renderAnimeOverlayFX();
  // Cap so a backgrounded tab / long stall can't make the AI fire instantly on return.
  updateAdaptiveAI(Math.min(delta, 100));
}

let lastTime = performance.now();
function animate3D(now) {
  if (vrActive) return;
  requestAnimationFrame(animate3D);
  runFrame(now);
}

function renderSceneView() {
  if (!renderer || !scene) return;
  const container = document.getElementById('webglContainer');
  const w = container.clientWidth, h = container.clientHeight;
  if (splitScreenOn && cameraP1 && cameraP2) {
    renderer.setScissorTest(true);
    renderer.setViewport(0, 0, w / 2, h); renderer.setScissor(0, 0, w / 2, h);
    renderer.render(scene, cameraP1);
    renderer.setViewport(w / 2, 0, w / 2, h); renderer.setScissor(w / 2, 0, w / 2, h);
    renderer.render(scene, cameraP2);
    renderer.setScissorTest(false);
    renderer.setViewport(0, 0, w, h);
  } else if (camera) {
    renderer.render(scene, camera);
  }
}


// ===================== SKELETON OVERLAY =====================
// Draws the player's body on the camera preview so they can see what the game sees
function drawSkeletonOverlay(ctx, landmarks, w, h) {
  if (!landmarks || landmarks.length < 33) return;

  // Connection lines between body parts
  const connections = [
    [11,12], [11,13], [13,15], [12,14], [14,16], // arms
    [11,23], [12,24], [23,24], // torso
    [23,25], [25,27], [24,26], [26,28], // legs
    [0,11], [0,12], // neck
  ];

  // Draw connection lines
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(56, 189, 248, 0.6)'; // cyan
  ctx.lineCap = 'round';
  for (const [a, b] of connections) {
    const la = landmarks[a], lb = landmarks[b];
    if (!la || !lb) continue;
    ctx.beginPath();
    ctx.moveTo(la.x * w, la.y * h);
    ctx.lineTo(lb.x * w, lb.y * h);
    ctx.stroke();
  }

  // Draw body part dots
  const keyPoints = [
    { idx: 15, label: 'L', color: '#38bdf8' }, // left wrist
    { idx: 16, label: 'R', color: '#38bdf8' }, // right wrist
    { idx: 27, label: 'L', color: '#10b981' }, // left ankle
    { idx: 28, label: 'R', color: '#10b981' }, // right ankle
    { idx: 11, label: '', color: '#94a3b8' },  // left shoulder
    { idx: 12, label: '', color: '#94a3b8' },  // right shoulder
    { idx: 23, label: '', color: '#94a3b8' },  // left hip
    { idx: 24, label: '', color: '#94a3b8' },  // right hip
  ];

  for (const pt of keyPoints) {
    const lm = landmarks[pt.idx];
    if (!lm) continue;
    const x = lm.x * w, y = lm.y * h;
    const vis = lm.visibility || 0;
    const radius = vis > 0.5 ? 6 : 4;
    const alpha = Math.max(0.3, vis);

    // Glow effect — convert hex to rgba with reduced alpha (the prior
    // .replace(')', ...) trick silently no-op'd on hex strings, leaving
    // the glow at full opacity and making the dots look harsh).
    ctx.beginPath();
    ctx.arc(x, y, radius + 4, 0, Math.PI * 2);
    ctx.fillStyle = hexToRgba(pt.color, alpha * 0.3);
    ctx.fill();

    // Solid dot
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = vis > 0.5 ? pt.color : '#ef4444';
    ctx.globalAlpha = alpha;
    ctx.fill();
    ctx.globalAlpha = 1;

    // Label
    if (pt.label) {
      ctx.font = 'bold 9px Orbitron';
      ctx.fillStyle = '#fff';
      ctx.fillText(pt.label, x + 8, y + 3);
    }
  }

  // Draw attack zones (hands and feet) with larger indicator
  const attackParts = [15, 16, 27, 28];
  for (const idx of attackParts) {
    const lm = landmarks[idx];
    if (!lm) continue;
    const x = lm.x * w, y = lm.y * h;
    // Pulsing ring
    const pulse = Math.sin(performance.now() * 0.005) * 0.3 + 0.7;
    ctx.beginPath();
    ctx.arc(x, y, 14, 0, Math.PI * 2);
    ctx.strokeStyle = idx <= 16 ? `rgba(56, 189, 248, ${pulse * 0.4})` : `rgba(16, 185, 129, ${pulse * 0.4})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Tracking quality bar at top
  const visibleCount = [11,12,15,16,23,24,27,28].filter(i => (landmarks[i]?.visibility || 0) > 0.5).length;
  const quality = visibleCount / 8;
  const barW = w - 16;
  ctx.fillStyle = 'rgba(0,0,0,0.5)';
  ctx.fillRect(8, 4, barW, 6);
  const qColor = quality > 0.75 ? '#10b981' : quality > 0.5 ? '#f59e0b' : '#ef4444';
  ctx.fillStyle = qColor;
  ctx.fillRect(8, 4, barW * quality, 6);

  // Quality text
  ctx.font = 'bold 8px Orbitron';
  ctx.fillStyle = qColor;
  ctx.fillText(quality > 0.75 ? 'TRACKING GOOD' : quality > 0.5 ? 'TRACKING OK' : 'ADJUST POSITION', 10, 18);
}


