// ===================== BOOT =====================
async function bootGame() {
  try {
    // Check for CDN script load failures — if critical globals are missing,
    // the CDN scripts failed (ad blocker, network issue, etc.)
    if (typeof THREE === 'undefined') {
      const overlay = document.getElementById('gameOverlay');
      document.getElementById('overlayTitle').innerHTML = '<span class="text-rose-400">RESOURCE LOAD ERROR</span>';
      document.getElementById('overlayDesc').textContent = 'The 3D engine (Three.js) failed to load. Check your internet connection, disable ad blockers for this site, and reload.';
      document.getElementById('overlayButtons').innerHTML = '<button onclick="location.reload()" class="cta-button cta-primary text-sm">RELOAD</button>';
      overlay.classList.remove('hidden');
      return;
    }
    // Wait for fonts to load so canvas text renders correctly
    if (document.fonts) { try { await document.fonts.load('700 16px Orbitron'); } catch(e) {} }
    init3DWorld();
    renderCharGrid('landingP1Grid', ch => { selectedP1Char = ch; }, selectedP1Char);
    renderCharGrid('landingP2Grid', ch => { selectedP2Char = ch; }, selectedP2Char);
    requestAnimationFrame(animate3D);
    sound.init();
    sound.startAmbient();

    // Observer panel is opt-in via ?test=1 (per docs/usability-test.md)
    if (new URLSearchParams(location.search).get('test') === '1') {
      usabilityObserver.enabled = true;
      mountUsabilityPanel();
    }

    // Show touch controls on mobile
    if (isMobile) {
      document.getElementById('touchControls').classList.add('active');
    }

    // Show overlay
    const overlay = document.getElementById('gameOverlay');
    document.getElementById('overlayTitle').textContent = 'ANIME MOTION FIGHTER';
    document.getElementById('overlayDesc').textContent = 'Stand where the camera can see you, or use keyboard/touch controls. Make clear hand or foot motions to attack.';
    document.getElementById('overlayButtons').innerHTML = `
      <button onclick="startMatch()" class="cta-button cta-primary text-sm"><i class="fa-solid fa-play mr-2"></i>START MATCH</button>
      <button onclick="openModeSelectModal()" class="cta-button cta-secondary text-sm"><i class="fa-solid fa-users mr-2"></i>CHANGE MODE</button>
    `;
    overlay.classList.remove('hidden');
  } catch (error) {
    console.error('Game boot failed', error);
    const overlay = document.getElementById('gameOverlay');
    document.getElementById('overlayTitle').innerHTML = '<span class="text-rose-400">ENGINE ERROR</span>';
    document.getElementById('overlayDesc').textContent = 'The 3D engine could not start. Try a modern browser with hardware acceleration.';
    document.getElementById('overlayButtons').innerHTML = '<button onclick="location.reload()" class="cta-button cta-primary text-sm">RELOAD</button>';
    overlay.classList.remove('hidden');
  }
}


// ===================== INIT =====================
window.addEventListener('DOMContentLoaded', async () => {
  // Loading sequence
  updateLoading(20, 'Loading 3D engine...');
  await new Promise(r => setTimeout(r, 300));
  updateLoading(50, 'Preparing arena...');
  await new Promise(r => setTimeout(r, 200));
  updateLoading(80, 'Loading fighters...');
  await new Promise(r => setTimeout(r, 200));
  updateLoading(100, 'Ready!');
  await new Promise(r => setTimeout(r, 300));

  hideLoading();
  loadSavedPrefs();
  document.getElementById('landingScreen').classList.remove('hidden');
  initLanding();
});

// Cleanup
window.addEventListener('pagehide', () => {
  dualCamRunning = false;
  stopCameraStream();
  dualCamLandmarker?.close?.(); dualCamLandmarker = null;
  renderer?.dispose?.();
});
window.addEventListener('error', (e) => console.error('[AMF]', e.error || e.message));
window.addEventListener('unhandledrejection', (e) => console.error('[AMF]', e.reason));


// ===================== SAVE + PREFS =====================
// Remembers your mode, fighters, mute setting and career record between visits.
// Everything stays in this browser's localStorage; every access is guarded because
// storage can be unavailable (private mode, blocked cookies, quota).
const SAVE_KEY = 'amf.save.v1';
let lastCareer = null;

function readSave() {
  try { return JSON.parse(localStorage.getItem(SAVE_KEY)) || {}; } catch (e) { return {}; }
}
function writeSave(patch) {
  try { localStorage.setItem(SAVE_KEY, JSON.stringify({ ...readSave(), ...patch })); } catch (e) { /* storage unavailable */ }
}

function savePrefs() {
  writeSave({ mode: selectedGameMode, p1: selectedP1Char.id, p2: selectedP2Char.id, muted: !!sound.muted });
}

function loadSavedPrefs() {
  const s = readSave();
  if (GAME_MODES.some(m => m.id === s.mode && !m.disabled)) selectedGameMode = s.mode;
  if (CHARACTERS[s.p1]) selectedP1Char = CHARACTERS[s.p1];
  if (CHARACTERS[s.p2]) selectedP2Char = CHARACTERS[s.p2];
  if (typeof s.muted === 'boolean') {
    sound.muted = s.muted;
    const btn = document.getElementById('muteBtn');
    if (btn && s.muted) btn.innerHTML = '<i class="fa-solid fa-volume-xmark"></i>';
  }
}

// Only Solo vs AI counts toward the career record.
function recordMatchResult(playerWon) {
  const c = { matches: 0, wins: 0, losses: 0, bestCombo: 0, topTier: 1, ...(readSave().career || {}) };
  c.matches++;
  if (playerWon) c.wins++; else c.losses++;
  c.bestCombo = Math.max(c.bestCombo, bestCombo);
  c.topTier = Math.max(c.topTier, gameLevel);
  writeSave({ career: c });
  return c;
}

// Pause automatically if the tab/window is hidden mid-fight (the AI and round timers keep running otherwise).
document.addEventListener('visibilitychange', () => {
  if (document.hidden && gameState === 'PLAYING' && !roundLocked) togglePause();
});
